# Quick price-performance check
models = [
    {"name": "Frontier A", "score": 56.8, "price_per_mtok": 10.0},
    {"name": "Budget B",  "score": 52.7, "price_per_mtok": 0.16},
]
for m in models:
    m["value"] = round(m["score"] / m["price_per_mtok"], 1)
for m in sorted(models, key=lambda x: -x["value"]):
    print(f'{m["name"]}: score {m["score"]} -> value index {m["value"]}')
